(()=>{
const schedule=[["08:30", "التجمع في المدارس."], ["09:00", "الانطلاق من المدارس نحو سهل البطوف."], ["10:00", "توزيع قمصان السباق + ترتيب المتسابقين + إحماء رياضي."], ["11:00", "بداية السباق."], ["12:00", "تتويج الفائزين وفعاليات اختتامية."], ["13:00", "العودة إلى المدارس."]],prizes=["ميدالية وقميص سباق رسمي لكل مشترك.", "كؤوس للمراتب الثلاث الأولى من كل فئة.", "جوائز قيمة للمدارس الأكثر مشاركة."],activities=["مأكولات ومشروبات خفيفة.", "رسم على الوجوه وفعاليات ممتعة للأطفال.", "صورة مغناطيسية تذكارية لكل مشترك."],schools=["ابن سينا", "الغزالي", "حسين ياسين", "ابن رشد", "البيروني", "الزهراء", "رأس العين"];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=v=>esc(I18N.t(v));
function program(){return `<section class="batouf-program"><div class="section-heading"><div><p class="eyebrow">${text('السبت 14.11.2026')}</p><h2>${text('برنامج يوم السباق')}</h2></div></div><ol class="batouf-timeline">${schedule.map(([time,label])=>`<li><time datetime="2026-11-14T${time}:00+02:00" dir="ltr">${time}</time><span>${text(label)}</span></li>`).join('')}</ol><div class="batouf-highlights"><section><h3>${text('الجوائز والتكريم')}</h3><ul>${prizes.map(p=>`<li>${text(p)}</li>`).join('')}</ul></section><section><h3>${text('يتخلل البرنامج')}</h3><ul>${activities.map(p=>`<li>${text(p)}</li>`).join('')}</ul></section></div><h3>${text('المدارس المشاركة')}</h3><ul class="batouf-schools">${schools.map(s=>`<li>${text(s)}</li>`).join('')}</ul></section>`}
function sponsors(e){return `<section class="section batouf-support"><p class="eyebrow">${text('معًا من أجل أبنائنا')}</p><h2>${text('المنظّمون والشركاء والداعمون')}</h2><div class="batouf-sponsors">${(e.sponsors||[]).map(s=>{const url=s.image?.url;const safe=url?.startsWith('/uploads/')?(window.API_BASE_URL||'')+url:url?.startsWith('assets/')?url:null;return `<article>${safe?`<img src="${esc(safe)}" alt="${esc(s.name)}" loading="lazy">`:''}<strong>${text(s.name)}</strong></article>`}).join('')}</div></section>`}
let current=RACE_EVENTS.find(e=>e.id==='arraba-2026');
function home(event){if(event)current=event;const section=document.querySelector('#batoufHome');if(!section||!current)return;const e=I18N.event(current);section.innerHTML=`<section class="section batouf-story"><p class="eyebrow">${text('عن السباق')}</p><h2>${text('سباق البطوف — عرابة')}</h2>${e.description.split(/\n\n/).map(p=>`<p>${esc(p)}</p>`).join('')}</section><div class="section">${program()}</div>${sponsors(current)}<section class="section batouf-album"><h2>${text('ألبوم السباق')}</h2><p>${text('ينشر في نهاية الحدث')}</p></section>`}
window.BatoufContent={program,home,sponsors};home();window.addEventListener('languagechange',()=>home());
})();
